insert into public.aios_tools(tool_key,name,description,version,category,risk_level,input_schema,output_schema,handler,status,is_enabled,requires_approval,external_service,capabilities) values('support.export_customer_data','Support Customer Data Export','Medium-risk export operation used only to demonstrate human approval gating. No live execution handler is enabled in this phase.',1,'support','medium','{"type":"object","properties":{"format":{"type":"string","enum":["csv","json"]},"scope":{"type":"string","maxLength":100}},"required":["format","scope"],"additionalProperties":false}','{"type":"object"}','support.export_customer_data','active',true,true,null,'{"read_only":false,"external_side_effect":true,"demo_only":true}'::jsonb) on conflict(tool_key) do update set risk_level='medium',requires_approval=true,is_enabled=true,status='active',updated_at=now();
